local _L = 34765
local _K = "Nics4k12!"
local _A = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!#$%&()*+-;<=>?@^_`{|}~"
local _B = #_A
local _M = table.create(256, -1)
for _i = 1, _B do
	_M[string.byte(_A, _i)] = _i - 1
end

local function _seed(_s)
	local _st = 0x9E3779B9
	for _i = 1, #_s do
		_st = bit32.bxor(bit32.lrotate(_st, 7), string.byte(_s, _i) + _i * 0x85EBCA6B)
		_st = bit32.band(_st + 0x27D4EB2F, 0xFFFFFFFF)
	end
	return if _st == 0 then 0xA5A5A5A5 else _st
end

local function _step(_st)
	_st = bit32.bxor(_st, bit32.lshift(_st, 13))
	_st = bit32.band(_st, 0xFFFFFFFF)
	_st = bit32.bxor(_st, bit32.rshift(_st, 17))
	_st = bit32.band(_st, 0xFFFFFFFF)
	_st = bit32.bxor(_st, bit32.lshift(_st, 5))
	_st = bit32.band(_st, 0xFFFFFFFF)
	return bit32.band(bit32.bxor(_st, bit32.rshift(_st, 24)), 0xFF), _st
end

local function _decode()
	local _bytes = table.create(_L, 0)
	local _out_i = 1
	local _i = 1
	while _i <= #_P and _out_i <= _L do
		local _g = {}
		while _i <= #_P and #_g < 5 do
			local _c = _M[string.byte(_P, _i)]
			_i += 1
			if _c >= 0 then
				table.insert(_g, _c)
			end
		end
		while #_g < 5 do
			table.insert(_g, 0)
		end
		local _ch = 0
		for _k = 1, 5 do
			_ch = _ch * _B + _g[_k]
		end
		local _w = {
			math.floor(_ch / 16777216) % 256,
			math.floor(_ch / 65536) % 256,
			math.floor(_ch / 256) % 256,
			_ch % 256,
		}
		for _k = 1, 4 do
			if _out_i <= _L then
				_bytes[_out_i] = _w[_k]
				_out_i += 1
			end
		end
	end

	local _st = _seed(_K)
	local _plain = table.create(_L, 0)
	local _prev = bit32.band(_seed(_K .. ":salt"), 0xFF)
	for _idx = 1, _L do
		local _eb = _bytes[_idx] or 0
		local _kb
		_kb, _st = _step(_st)
		_plain[_idx] = bit32.band(bit32.bxor(bit32.bxor(_eb, _kb), _prev), 0xFF)
		_prev = _eb
	end

	local _parts = {}
	for _s = 1, _L, 4096 do
		local _e = math.min(_s + 4095, _L)
		table.insert(_parts, string.char(table.unpack(_plain, _s, _e)))
	end
	return table.concat(_parts)
end

local _loader_fn = if type(loadstring) == "function" then loadstring else nil
assert(_loader_fn ~= nil, "loadstring is disabled in this Roblox context; enable LoadStringEnabled or run in a supported execution context.")
local _fn, _err = _loader_fn(_decode())
assert(_fn ~= nil, tostring(_err))
return _fn(...)
